import{_ as t,c as n,o as i,aj as a}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"ConfinedYDocument","description":"","frontmatter":{},"headers":[],"relativePath":"reference/swift-client/ConfinedYDocument.md","filePath":"reference/swift-client/ConfinedYDocument.md"}'),o={name:"reference/swift-client/ConfinedYDocument.md"};function s(c,e,d,r,l,h){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="confinedydocument" tabindex="-1"><code>ConfinedYDocument</code> <a class="header-anchor" href="#confinedydocument" aria-label="Permalink to “ConfinedYDocument”">​</a></h1><p><code>struct</code> — swift-client/Sources/JsBaoClient/Types/DocumentTypes.swift</p><p>The one holder that carries a live <code>YDocument</code> across an isolation boundary, and the one place the safety argument for doing so is written down (Phase C).</p><p><code>YDocument</code> (from the <code>YSwift</code> fork) is a reference type wrapping yrs FFI state and is not <code>Sendable</code>. Rather than let each type that needs to hand a document to another isolation domain grow its own <code>@unchecked Sendable</code> conformance — which is how two holders with two different (and unverifiable) arguments appear — every such type wraps the document in this value and becomes plainly <code>Sendable</code> itself. <code>OpenDocumentResult</code> below is the first adopter; <code>DocumentManager</code>&#39;s document handoffs are the next (Phase D).</p><h2 id="unchecked-sendable-—-safety-argument" tabindex="-1"><code>@unchecked Sendable</code> — safety argument <a class="header-anchor" href="#unchecked-sendable-—-safety-argument" aria-label="Permalink to “@unchecked Sendable — safety argument”">​</a></h2><ul><li><code>document</code> is a <code>let</code>; the holder itself has no mutable state, so <em>transferring</em> it is a copy of one reference and nothing else.</li><li>The document it points at is <strong>lock-confined, not isolation-confined</strong>: every raw-FFI mutation and every read on <code>YDocument</code> runs inside <code>withExclusiveAccess</code> / <code>transact</code> / <code>transactSync</code>, all of which serialize on the document&#39;s single <code>ffiLock</code> (<code>yswift-fork/Sources/YSwift/YDocument.swift:53,61</code>). That lock is an <code>NSRecursiveLock</code> <strong>by design</strong> — the observer path re-enters it while a transaction on the same thread is open — so the guarantee is mutual exclusion between threads, not non-reentrancy on one thread.</li><li>So two isolation domains holding the same document is safe in exactly the way two threads holding it is safe: their operations interleave at transaction granularity under <code>ffiLock</code>. What it does NOT give you is ordering across the sync and async transaction paths, which serialize on separate queues — never split one logical batch across <code>transact</code> and <code>transactSync</code> (the same invariant <code>DynamicModel</code> records).</li></ul><p>Unwrapping is deliberately explicit (<code>.document</code>) so a reviewer can grep for the points where a confined document re-enters ordinary code.</p><h2 id="document" tabindex="-1"><code>document</code> <a class="header-anchor" href="#document" aria-label="Permalink to “document”">​</a></h2><div class="language-swift"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document: YDocument</span></span></code></pre></div><p>The live, editable document. Every access still goes through the document&#39;s own transaction API, which takes <code>ffiLock</code>.</p><h2 id="init" tabindex="-1"><code>init</code> <a class="header-anchor" href="#init" aria-label="Permalink to “init”">​</a></h2><div class="language-swift"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document: YDocument)</span></span></code></pre></div>',12)])])}const f=t(o,[["render",s]]);export{p as __pageData,f as default};
